// Review the frozen source snapshot and download the already generated bytes.
// Source loading errors never turn a short Saved preview into exported code.
export function openReportExportReview({ prepare, isCurrent }) {
  const dialog = document.createElement("dialog");
  dialog.className = "report-export-review";
  const titleID = `report-export-title-${crypto.randomUUID()}`;
  dialog.setAttribute("aria-labelledby", titleID);
  const header = document.createElement("header");
  const title = document.createElement("h2");
  title.id = titleID;
  title.textContent = "Review Report";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "report-export-close";
  close.setAttribute("aria-label", "Close export review");
  close.textContent = "×";
  header.append(title, close);
  const status = document.createElement("p");
  status.className = "report-export-status";
  status.setAttribute("role", "status");
  const content = document.createElement("section");
  content.className = "report-export-content";
  content.setAttribute("aria-label", "Report export preview");
  const footer = document.createElement("footer");
  const retry = document.createElement("button");
  retry.type = "button";
  retry.textContent = "Try again";
  retry.hidden = true;
  const download = document.createElement("button");
  download.type = "button";
  download.className = "report-export-download";
  download.textContent = "Download PDF";
  download.disabled = true;
  footer.append(retry, download);
  dialog.append(header, status, content, footer);
  let disposed = false;
  let packet = null;
  const objectURLs = new Set();
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    clearInterval(contextCheck);
    objectURLs.forEach(url => URL.revokeObjectURL(url));
    packet = null;
    content.replaceChildren();
    dialog.remove();
  };
  const current = () => !disposed && isCurrent();
  const contextCheck = setInterval(() => {
    if (!current()) { dialog.close(); dispose(); }
  }, 200);
  close.addEventListener("click", () => dialog.close());
  dialog.addEventListener("close", dispose, { once: true });
  const load = async () => {
    packet = null;
    objectURLs.forEach(url => URL.revokeObjectURL(url));
    objectURLs.clear();
    retry.hidden = true;
    download.disabled = true;
    content.replaceChildren();
    status.setAttribute("role", "status");
    status.textContent = "Loading the saved Report PDF…";
    try {
      if (!current()) { dispose(); return; }
      const prepared = await prepare();
      if (!current()) { dispose(); return; }
      if (!prepared.manifest?.items?.length || !prepared.pdfBlob) throw new Error("The stored Report PDF is unavailable. Please try again.");
      packet = prepared;
      const manifest = packet.manifest;
      const selections = manifest.sourceVersions?.selections || [];
      status.textContent = `${manifest.project.name} · Version ${manifest.reportVersion || 1}${selections.some(source => source.hasTables) ? " · Tables included as text" : ""}`;
      manifest.items.forEach(item => {
        if (item.kind === "evidence") {
          const article = document.createElement("article");
          const meta = document.createElement("p");
          meta.className = "report-export-source";
          meta.textContent = `${item.codeBook} · ${item.codeEdition} · § ${item.sectionNumber}`;
          const heading = document.createElement("h3");
          heading.textContent = item.title;
          const text = document.createElement("p");
          text.className = "report-export-passage";
          text.textContent = item.passageText;
          article.append(meta, heading, text);
          content.append(article);
        } else if (item.kind === "heading") {
          const heading = document.createElement("h3");
          heading.className = "report-export-note-heading";
          heading.textContent = item.text;
          content.append(heading);
        } else if (item.kind === "paragraph") {
          const paragraph = document.createElement("p");
          paragraph.className = "report-export-note";
          paragraph.textContent = item.text;
          content.append(paragraph);
        } else if (item.kind === "list") {
          const list = document.createElement("ul");
          item.items.forEach(value => { const row = document.createElement("li"); row.textContent = value; list.append(row); });
          content.append(list);
        } else {
          const article = document.createElement("article");
          const heading = document.createElement("h3");
          heading.textContent = item.title || item.question || item.kind;
          const text = document.createElement("p");
          text.className = "report-export-passage";
          if (item.kind === "projectFacts") text.textContent = [item.address, item.facts].filter(Boolean).join("\n\n");
          else if (item.kind === "notebookCard") text.textContent = item.plainText;
          else if (item.kind === "researchAnswer") {
            text.textContent = [item.answerText || item.conclusion, item.explanation,
              ...(item.supportedPoints || []).map(point => typeof point === "string" ? point : [point.heading, point.explanation].filter(Boolean).join(": ")),
              ...(item.assumptions || []).map(value => `Assumption: ${value}`),
              ...(item.missingFacts || []).map(value => `Project fact to verify: ${value}`),
              ...(item.limitations || []).map(value => `Limit: ${value}`),
              ...(item.additionalEvidenceNeeded || []).map(value => `Related evidence to add: ${value}`),
              item.authorityLabel, item.codeBasis?.disclosure, item.codeBasis?.limitation, item.disclaimer].filter(Boolean).join("\n\n");
          } else text.textContent = "Included project material. Open the PDF preview below to inspect its layout.";
          article.append(heading, text);
          content.append(article);
        }
      });
      const notice = document.createElement("p");
      notice.className = "report-export-notice";
      notice.textContent = manifest.disclaimers.join(" ");
      content.append(notice);
      const previewURL = URL.createObjectURL(packet.pdfBlob);
      objectURLs.add(previewURL);
      const preview = document.createElement("a");
      preview.href = previewURL;
      preview.target = "_blank";
      preview.rel = "noopener";
      preview.textContent = "Open PDF preview";
      content.append(preview);
      download.disabled = false;
    } catch (error) {
      if (!current()) { dispose(); return; }
      status.setAttribute("role", "alert");
      status.textContent = error.message || "Could not load the complete source text. Please try again.";
      retry.hidden = false;
    }
  };
  retry.addEventListener("click", () => void load());
  download.addEventListener("click", () => {
    if (!current()) { dialog.close(); dispose(); return; }
    if (!packet) return;
    const url = URL.createObjectURL(packet.pdfBlob);
    objectURLs.add(url);
    const link = document.createElement("a");
    link.href = url;
    link.download = packet.filename || "permitext-report.pdf";
    link.click();
    // Keep the reviewed snapshot available for another download until closed.
  });
  document.body.append(dialog);
  dialog.showModal();
  void load();
  return dialog;
}
